export type Shelf = keyof typeof SHELVES

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

/** An HTML list linking every listing on the given shelves. */
export function stockList(shelves: Shelf[]): string {
  const items = shelves.flatMap((s) => SHELVES[s] as Listing[])
  return `<ul>${items.map((l) => `<li><a href="/p/${l.slug}">${esc(l.title)}</a></li>`).join('')}</ul>`
}
